 ['the origin is top left, y grows downward, and pixels lie in rows', "from PIL import Image\nim = Image.new('L', (28, 27))\nim.putpixel((3, 1), 200)\ndata = im.tobytes()\nprint(len(data), data.index(200), 1 * 28 + 3)", '756 31 31'],
